/* Types */
/**  Appareil Android du sélecteur (glossaire : `AndroidDevice`). */
export type AndroidDevice = {
	/**  Clé du choix gardé : nom de l'AVD d'un émulateur, sinon série. */
	id: string,
	/**  Nom affiché : AVD ou modèle, soulignés changés en espaces ; série à défaut. */
	name: string,
	emulator: boolean,
	avd: string | null,
	/**  Série adb, présente si l'appareil est démarré ou branché. */
	serial: string | null,
};

/**  Erreurs de l'app. Sérialisées vers le front : `{ kind, message }`. */
export type AppError = { kind: "Database"; message: string } | 
/**  Le chemin n'existe pas (ou n'est pas absolu). Porte le chemin demandé. */
{ kind: "NotFound"; message: string } | 
/**  Un fichier là où un dossier est attendu. Porte le chemin demandé. */
{ kind: "NotADirectory"; message: string } | 
/**  Un dossier là où un fichier est attendu. Porte le chemin demandé. */
{ kind: "NotAFile"; message: string } | 
/**  macOS refuse l'accès. Porte le chemin demandé. */
{ kind: "PermissionDenied"; message: string } | 
/**  Une entrée de ce nom existe déjà. Porte le chemin demandé. */
{ kind: "AlreadyExists"; message: string } | 
/**  Nom de fichier ou de dossier refusé (vide, `.`, `..`, `/`, nul). Porte le nom saisi. */
{ kind: "InvalidName"; message: string } | 
/**  Le fichier a changé sur le disque depuis sa lecture : rien n'est écrit. Porte le chemin. */
{ kind: "Conflict"; message: string } | 
/**
 *  Une commande git d'écriture a échoué (hook, identité absente, rien à committer, patch
 *  refusé). Porte la sortie de git (standard et d'erreur), affichée telle quelle.
 */
{ kind: "Git"; message: string } | 
/**
 *  Un geste réseau git a échoué (récupérer, pousser, tirer : spec `git-distant.md`).
 *  `kind` est le genre reconnu, `output` la sortie de git telle quelle (vide pour
 *  `NoRemote`, `AmbiguousRemote` et `Timeout`).
 */
{ kind: "Remote"; message: {
	kind: RemoteErrorKind,
	output: string,
} } | 
/**
 *  Les issues GitHub ne sont pas disponibles (spec `issues-github.md`) : le front affiche
 *  le message de la raison.
 */
{ kind: "GithubUnavailable"; message: GithubUnavailable } | 
/**  L'issue demandée n'existe pas (supprimée, transférée). Le front connaît son numéro. */
{ kind: "IssueNotFound" } | 
/**  Autre échec de `gh` (ou sortie illisible) : sa sortie d'erreur, telle quelle. */
{ kind: "Gh"; message: string } | 
/**
 *  Adresse refusée par le champ d'URL du navigateur (spec `navigateur.md`). Porte le genre
 *  du refus, traduit par le front.
 */
{ kind: "InvalidUrl"; message: UrlError } | 
/**  Échec du navigateur intégré (webview impossible à créer ou à placer). */
{ kind: "Browser"; message: string } | 
/**
 *  App lancée hors d'un paquet `.app` (`tauri dev`) : impossible d'en faire l'app par
 *  défaut d'un type (spec `app-par-defaut.md`). Rien n'est demandé à macOS.
 */
{ kind: "NotBundled" } | 
/**  Autre erreur d'entrée-sortie. */
{ kind: "Io"; message: string } | 
/**
 *  Échec dont la phrase est écrite par l'app : Rust n'envoie que le genre et les données
 *  brutes, le front traduit (spec `langue-interface.md`).
 */
{ kind: "Failed"; message: Failure };

/**
 *  Genre d'app native : plateforme d'une app Xcode, fenêtre Tauri ou Electron, binaire Rust
 *  (`cargo run`), exécutable d'un paquet Swift (`swift run`), app Android (Gradle), app Flutter
 *  (`flutter run`), ou cible d'un paquet Expo ou React Native (sa plateforme est sa source
 *  d'appareils).
 */
export type AppKind = "ios" | "watchos" | "tvos" | "visionos" | "macos" | 
/**  iOS exécuté sur le Mac (`SUPPORTS_MACCATALYST = YES`). */
"catalyst" | "tauri" | "electron" | "rust" | "swift" | "flutter" | "android" | "expo" | "reactNative";

/**
 *  Cible d'une app : une façon de la lancer (glossaire : `AppTarget`). Porte son propre état
 *  dans le front (page de terminal, En cours).
 */
export type AppTarget = {
	/**  Stable et unique dans l'app : « ios », « macos », « script:<nom> ». */
	id: string,
	/**  « iOS », « macOS », « tauri dev », « desktop ». */
	label: string,
	kind: AppKind,
	/**  Appareils proposés par le sélecteur ; `None` : pas de sélecteur. */
	deviceSource: DeviceSource | null,
	/**  Chemin absolu du `.xcodeproj` ou `.xcworkspace` (Xcode), ou dossier du projet Gradle. */
	project: string | null,
	/**
	 *  Schéma Xcode, chemin Gradle du module d'application (`:app`), ou commande de base
	 *  d'Expo et de React Native (`pnpm expo run:ios`).
	 */
	scheme: string | null,
	/**  Commande fixe (Tauri) ; `None` : construite par `get_app_command` selon `kind`. */
	command: string | null,
};

